import http from "node:http";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import crypto from "node:crypto";

const DATA_DIR = path.dirname(fileURLToPath(import.meta.url));
const DATA_FILE = path.join(DATA_DIR, "books.json");
const PORT = process.env.PORT || 3000;

async function loadBooks() {
  try {
    return JSON.parse(await readFile(DATA_FILE, "utf8"));
  } catch {
    return [];
  }
}

async function saveBooks(books) {
  await mkdir(DATA_DIR, { recursive: true });
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2));
}

const esc = (s = "") =>
  String(s).replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
  );

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)} · My Books</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 640px; margin: 2rem auto; padding: 0 1rem; color: #222; }
  h1 { font-size: 1.5rem; }
  a { color: #06c; }
  ul { list-style: none; padding: 0; }
  li { padding: .5rem 0; border-bottom: 1px solid #eee; display: flex; justify-content: space-between; align-items: center; gap: 1rem; }
  form { display: grid; gap: .5rem; margin: 1rem 0 2rem; }
  input, textarea { padding: .5rem; font: inherit; border: 1px solid #ccc; border-radius: 4px; }
  button { padding: .5rem 1rem; font: inherit; border: 0; border-radius: 4px; background: #06c; color: #fff; cursor: pointer; }
  .done { color: #777; }
  .muted { color: #777; font-size: .9rem; }
  .inline { display: inline; margin: 0; }
  .inline button { background: none; color: #06c; padding: 0; font-size: .9rem; text-decoration: underline; }
</style>
</head>
<body>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const finish = book.finished
    ? ""
    : `<form class="inline" method="post" action="/books/${book.id}/finish"><button type="submit">mark finished</button></form>`;
  return `<li class="${book.finished ? "done" : ""}">
    <a href="/books/${book.id}">${esc(book.title)}</a> <span class="muted">— ${esc(book.author)}</span>
    ${finish}
  </li>`;
}

function homePage(books) {
  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);
  const body = `
<h1>My Books</h1>

<h2>Add a book</h2>
<form method="post" action="/books">
  <input name="title" placeholder="Title" required>
  <input name="author" placeholder="Author" required>
  <textarea name="notes" placeholder="Notes (optional)" rows="3"></textarea>
  <button type="submit">Add book</button>
</form>

<h2>Currently reading (${reading.length})</h2>
<ul>${reading.map(bookItem).join("") || "<li class='muted'>Nothing right now.</li>"}</ul>

<h2>Finished (${finished.length})</h2>
<ul>${finished.map(bookItem).join("") || "<li class='muted'>Nothing yet.</li>"}</ul>`;
  return layout("My Books", body);
}

function bookPage(book) {
  const body = `
<p><a href="/">&larr; all books</a></p>
<h1>${esc(book.title)}</h1>
<p class="muted">by ${esc(book.author)}</p>
<p>Status: ${book.finished ? "Finished" : "Currently reading"}</p>
<h2>Notes</h2>
<p>${book.notes ? esc(book.notes).replace(/\n/g, "<br>") : "<span class='muted'>No notes.</span>"}</p>
${
  book.finished
    ? ""
    : `<form method="post" action="/books/${book.id}/finish"><button type="submit">Mark finished</button></form>`
}`;
  return layout(book.title, body);
}

async function readBody(req) {
  let data = "";
  for await (const chunk of req) data += chunk;
  return new URLSearchParams(data);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function notFound(res) {
  res.writeHead(404, { "Content-Type": "text/html" });
  res.end(layout("Not found", `<h1>404</h1><p><a href="/">Go home</a></p>`));
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const books = await loadBooks();

  if (req.method === "GET" && url.pathname === "/") {
    res.writeHead(200, { "Content-Type": "text/html" });
    return res.end(homePage(books));
  }

  if (req.method === "POST" && url.pathname === "/books") {
    const body = await readBody(req);
    const title = (body.get("title") || "").trim();
    const author = (body.get("author") || "").trim();
    if (title && author) {
      books.push({
        id: crypto.randomUUID(),
        title,
        author,
        notes: (body.get("notes") || "").trim(),
        finished: false,
        addedAt: new Date().toISOString(),
      });
      await saveBooks(books);
    }
    return redirect(res, "/");
  }

  const bookMatch = url.pathname.match(/^\/books\/([\w-]+)$/);
  if (req.method === "GET" && bookMatch) {
    const book = books.find((b) => b.id === bookMatch[1]);
    if (!book) return notFound(res);
    res.writeHead(200, { "Content-Type": "text/html" });
    return res.end(bookPage(book));
  }

  const finishMatch = url.pathname.match(/^\/books\/([\w-]+)\/finish$/);
  if (req.method === "POST" && finishMatch) {
    const book = books.find((b) => b.id === finishMatch[1]);
    if (!book) return notFound(res);
    book.finished = true;
    book.finishedAt = new Date().toISOString();
    await saveBooks(books);
    return redirect(res, `/books/${book.id}`);
  }

  notFound(res);
});

server.listen(PORT, () => {
  console.log(`Book tracker running at http://localhost:${PORT}`);
});

